  'deleteRunningConfirm': ['{label} #{number} đang chạy hoặc đang chờ. Hệ thống sẽ hoàn thành tác vụ nhỏ đang chạy, dừng lại rồi xóa toàn bộ dữ liệu đã tạo. Tiếp tục?', '{label} #{number} is running or queued. It will finish the current small task, stop, then delete all data it created. Continue?'],
  'laneStatus': ['Chạy song song {workflows} workflow · workflow này dùng {units}/{target} luồng · {cores} lõi CPU', 'Running {workflows} workflows · this workflow uses {units}/{target} lanes · {cores} CPU cores'],
  'laneYielding': ['Đang nhường tài nguyên cho workflow #{workflow}', 'Yielding resources to workflow #{workflow}'],
  'laneWaiting': ['Đang chờ các workflow chạy sau nhả RAM', 'Waiting for later workflows to release RAM'],
  'Tự tạm dừng vì thiếu tài nguyên khi chạy nhiều workflow; sẽ tự tiếp tục khi đủ tài nguyên.': ['Tự tạm dừng vì thiếu tài nguyên khi chạy nhiều workflow; sẽ tự tiếp tục khi đủ tài nguyên.', 'Paused automatically because several workflows need more resources; it resumes when resources are free.'],
  'translationPrefixProgress': ['Đã lưu {done}/{total} đoạn · đã xuất liên tiếp {exported} đoạn từ đầu.', '{done}/{total} segments saved · {exported} contiguous segments exported from the start.'],
  'Hoãn hiệu chỉnh CPU khi RAM ít': ['Hoãn hiệu chỉnh CPU khi RAM ít', 'CPU calibration deferred while memory is limited'],
  'memoryWaitNote': ['Đang chờ RAM: {seconds}s; tự dừng tạm sau {limit}s nếu chưa đủ. Thời gian chờ được tách khỏi thời gian xử lý bước.', 'Waiting for RAM: {seconds}s; pauses automatically after {limit}s if memory remains insufficient. Waiting time is excluded from stage processing time.'],
  'Thiếu RAM sau thời gian chờ; đã dừng tạm và giữ checkpoint. Có thể tiếp tục khi RAM khả dụng tăng.': ['Thiếu RAM sau thời gian chờ; đã dừng tạm và giữ checkpoint. Có thể tiếp tục khi RAM khả dụng tăng.', 'Insufficient RAM after waiting; paused with checkpoints preserved. Resume when more memory is available.'],
