  'DOWNLOADING': ['Đang tải Audio', 'Downloading Audio'], 'VAD': ['Đang tách lời nói', 'Detecting speech'], 'TRANSCRIBING': ['Đang chép lời', 'Transcribing'], 'MERGING': ['Đang ghép bản chép', 'Merging transcript'], 'TRANSCRIPTION_COMPLETED': ['Đã chép tiếng Trung', 'Chinese transcribed'], 'TRANSLATING': ['Đang dịch tiếng Việt', 'Translating to Vietnamese'], 'TRANSLATION_COMPLETED': ['Đã dịch', 'Translated'], 'MODERATING': ['Đang kiểm duyệt', 'Moderating'], 'MODERATION_COMPLETED': ['Đã kiểm duyệt', 'Moderated'], 'TTS_GENERATING': ['Đang tạo giọng Việt', 'Generating Vietnamese voice'],
  'Original phải có nội dung; Replacement phải là chuỗi (có thể để trống).': ['Từ gốc phải có nội dung; phần thay thế phải là chuỗi (có thể để trống).', 'Original must not be empty; replacement must be text (may be empty).'], 'Original tối đa 1.000 ký tự; Replacement tối đa 10.000 ký tự.': ['Từ gốc tối đa 1.000 ký tự; phần thay thế tối đa 10.000 ký tự.', 'Original allows up to 1,000 characters; replacement allows up to 10,000.'], 'Original đã có trong danh sách.': ['Từ gốc đã có trong danh sách.', 'Original already exists.'], 'Không tìm thấy rule.': ['Không tìm thấy quy tắc.', 'Rule not found.'], 'Không thể đọc/ghi replacement rules.': ['Không thể đọc/ghi quy tắc thay thế.', 'Cannot read or write replacement rules.'],
