const lookup = new Map<string, readonly [string, string]>();
for (const [key, pair] of Object.entries(uiText)) {
  lookup.set(key, pair);
  if (!lookup.has(pair[0])) lookup.set(pair[0], pair);
  if (!lookup.has(pair[1])) lookup.set(pair[1], pair);
}
function registerMessages(vi: object, en: object) {
  for (const key of Object.keys(vi)) {
    const left = (vi as Record<string, unknown>)[key];
    const right = (en as Record<string, unknown>)[key];
    if (typeof left === 'string' && typeof right === 'string') {
      const pair = [left, right] as const;
      if (!lookup.has(left)) lookup.set(left, pair);
      if (!lookup.has(right)) lookup.set(right, pair);
    } else if (left && right && typeof left === 'object' && typeof right === 'object') registerMessages(left, right);
  }
}
registerMessages(translations.vi, translations.en);

const resourceMessages: [RegExp, string, string][] = [
  [/^Tự tạm dừng để ưu tiên workflow #(\d+); sẽ tự tiếp tục khi đủ tài nguyên\.$/, 'Tự tạm dừng để ưu tiên workflow #$1; sẽ tự tiếp tục khi đủ tài nguyên.', 'Paused automatically to let workflow #$1 finish first; it resumes when resources are free.'],
  [/^RAM trống ([\d.]+) GB; cần dự phòng ([\d.]+) GB cho workflow mới và các workflow chưa nạp model \(đã giữ ([\d.]+) GB cho hệ thống\)\.$/, 'RAM trống $1 GB; cần dự phòng $2 GB cho quy trình mới và các quy trình chưa nạp mô hình (đã giữ $3 GB cho hệ thống).', '$1 GB RAM available; $2 GB is required for the new workflow and workflows with unloaded models ($3 GB reserved for the system).'],
  [/^(\d+) workflow đồng thời cần dự toán ([\d.]+) GB, vượt RAM tổng ([\d.]+) GB\.$/, '$1 quy trình đồng thời cần khoảng $2 GB, vượt tổng RAM $3 GB.', '$1 concurrent workflows need an estimated $2 GB, exceeding the total RAM of $3 GB.'],
  [/^Dự toán (\d+) luồng cho (\d+) workflow, nhưng máy có (\d+) lõi CPU vật lý\.$/, 'Dự toán $1 luồng cho $2 quy trình, nhưng máy có $3 lõi CPU vật lý.', 'An estimated $1 threads for $2 workflows exceed the $3 physical CPU cores.'],
  [/^CPU đang dùng ([\d.]+)%; chưa có đủ khoảng trống dưới mục tiêu ([\d.]+)% để thêm tải\.$/, 'CPU đang dùng $1%; chưa có đủ khoảng trống dưới mục tiêu $2% để thêm tải.', 'CPU usage is $1%; there is insufficient headroom below the $2% target to add work.'],
];

export function translateUi(text: string, language: Language, values?: Record<string, string | number>): string {
  let translated = lookup.get(text)?.[language === 'vi' ? 0 : 1] ?? text;
  if (translated === text) {
    for (const [pattern, vi, en] of resourceMessages) {
      if (pattern.test(text)) { translated = text.replace(pattern, language === 'vi' ? vi : en); break; }
    }
  }
  return translated.replace(/\{(\w+)\}/g, (placeholder, key: string) => values?.[key] == null ? placeholder : String(values[key]));
}

export function translateVoiceDescription(description: string, language: Language): string {
  if (language === 'vi') return description;
  const parts = description.split(' · ');
  if (parts.length !== 3) return description;
  const gender: Record<string, string> = { Nam: 'Male', Nữ: 'Female' };
  const region: Record<string, string> = { Bắc: 'Northern', Trung: 'Central', Nam: 'Southern' };
  const style: Record<string, string> = { 'Phong cách tự nhiên': 'Natural style', 'Phong cách kể chuyện': 'Storytelling style', 'Phong cách tin tức': 'News style', 'Giọng đọc tự nhiên': 'Natural voice', 'Phong cách đọc truyện': 'Narration style' };
  return [gender[parts[0]] || parts[0], region[parts[1]] || parts[1], style[parts[2]] || parts[2]].join(' · ');
}
